/**
 * @description Business data in the answer or callback (event option Business Data In Response): a background job runs
 * the event's Response Handler Class with the stored body and its "data" object, then sets Business Status Done (with
 * the handler's result line) or Failed (with the error). The delivery Status is never changed by a handler error.
 * One job takes the whole list of transactions and chains itself for the rest. Admins can rerun a Failed handler.
 * @group Integration Hub
 */
public with sharing class IntegrationHubBusiness implements Queueable {

    /** @description Business Status while the handler waits or runs. */
    public static final String PROCESSING = 'Processing';
    /** @description Business Status after the handler ran without error. */
    public static final String DONE = 'Done';
    /** @description Business Status after the handler failed. */
    public static final String FAILED = 'Failed';
    /** @description Integration Attempt kind of a rerun. */
    public static final String KIND_RERUN = 'Handler Rerun';

    private static final Integer MAX_PER_JOB = 50;
    private static final Integer LIMIT_MARGIN = 30;
    private static final String NOT_RUN = 'Not run: too many background jobs in this transaction. Use Rerun handler.';
    private static final String FIELDS = 'Id, Name, Event__c, Event_Name__c, Direction__c, Status__c, Related_Record_Id__c, '
        + 'Related_Object__c, Http_Status_Code__c, Response_Body__c, Callback_Body__c, External_Reference_Id__c, Correlation_Id__c, '
        + 'Business_Status__c, Business_Result__c, Business_Runs__c';

    private final List<Id> ids;

    /**
     * @description A job for these transactions.
     * @param transactionIds the transactions (Business Status Processing)
     */
    public IntegrationHubBusiness(List<Id> transactionIds) {
        ids = transactionIds == null ? new List<Id>() : transactionIds;
    }

    /**
     * @description Queues ONE job for all these transactions. When no job can be queued they get Business Status
     * Failed, so they can be rerun. In a test, a job already running does not queue another (tests run it directly).
     * @param transactionIds the transactions
     */
    public static void enqueue(List<Id> transactionIds) {
        if (transactionIds == null || transactionIds.isEmpty() || (Test.isRunningTest() && System.isQueueable())) {
            return;
        }
        if (Limits.getQueueableJobs() < Limits.getLimitQueueableJobs()) {
            System.enqueueJob(new IntegrationHubBusiness(transactionIds));
        } else {
            markFailed(transactionIds, NOT_RUN);
        }
    }

    /**
     * @description Runs the Response Handler Class again for a transaction whose Business Status is Failed. Admins only.
     * Logs an Integration Attempt of kind Handler Rerun and queues the job.
     * @param transactionId the transaction
     */
    @AuraEnabled
    public static void rerun(Id transactionId) {
        IntegrationHubMonitorController.requireAdmin();
        IH_Transaction__c t = transactionId == null ? null : (IH_Transaction__c) IntegrationHubData.queryFirst(
            'SELECT Id, Business_Status__c FROM IH_Transaction__c WHERE Id = :id LIMIT 1', new Map<String, Object>{ 'id' => transactionId });
        if (t == null || t.Business_Status__c != FAILED) {
            String message = 'Only a transaction whose Business Status is Failed can be rerun.';
            AuraHandledException e = new AuraHandledException(message);
            e.setMessage(message);
            throw e;
        }
        IntegrationHubData.updateAll(new List<IH_Transaction__c>{
            new IH_Transaction__c(Id = t.Id, Business_Status__c = PROCESSING, Business_Error__c = null) });
        IntegrationHubData.insertAll(new List<IH_Attempt__c>{ new IH_Attempt__c(Transaction__c = t.Id, Kind__c = KIND_RERUN,
            Attempted_At__c = System.now(), Outcome__c = PROCESSING) });
        enqueue(new List<Id>{ t.Id });
    }

    /**
     * @description The "data" object of a JSON body.
     * @param body the answer or callback body
     * @return the data object, or null when the body is not JSON or has no "data" object
     */
    public static Map<String, Object> dataOf(String body) {
        Object data = IntegrationHubInbound.parseObject(body)?.get('data');
        return data instanceof Map<String, Object> ? (Map<String, Object>) data : null;
    }

    /**
     * @description Runs the handlers of the transactions that fit this job and chains a job for the rest.
     * @param qc the queueable context
     */
    public void execute(QueueableContext qc) {
        List<Id> chunk = new List<Id>();
        List<Id> rest = new List<Id>();
        for (Id txnId : ids) {
            if (chunk.size() < MAX_PER_JOB) {
                chunk.add(txnId);
            } else {
                rest.add(txnId);
            }
        }
        System.attachFinalizer(new Recovery(chunk));
        List<IH_Transaction__c> txns = (List<IH_Transaction__c>) IntegrationHubData.query(
            'SELECT ' + FIELDS + ' FROM IH_Transaction__c WHERE Id IN :ids AND Business_Status__c = :p',
            new Map<String, Object>{ 'ids' => chunk, 'p' => PROCESSING });
        Map<Id, IH_Event__c> events = IntegrationHubOutcome.events(txns);
        List<IH_Transaction__c> rows = new List<IH_Transaction__c>();
        for (IH_Transaction__c t : txns) {
            if (limitsNear()) {
                rest.add(t.Id);
            } else {
                rows.add(IntegrationHubBusinessRun.runOne(t, events.get(t.Event__c)));
            }
        }
        save(rows);
        if (!rest.isEmpty() && !Test.isRunningTest()) {
            enqueue(rest);
        }
    }

    private static Boolean limitsNear() {
        return Limits.getQueries() > Limits.getLimitQueries() - LIMIT_MARGIN
            || Limits.getDmlStatements() > Limits.getLimitDmlStatements() - LIMIT_MARGIN
            || Limits.getCpuTime() > Limits.getLimitCpuTime() / 2;
    }

    private static void save(List<IH_Transaction__c> rows) {
        IntegrationHubData.Outcome outcome = IntegrationHubData.updateEach(rows);
        List<IH_Transaction__c> refused = new List<IH_Transaction__c>();
        for (Integer i = 0; i < rows.size(); i++) {
            if (outcome.errorAt(i) != null) {
                rows[i].Business_Status__c = FAILED;
                rows[i].Business_Error__c = IntegrationHub.clip('The handler ran but the transaction could not be saved: ' + outcome.errorAt(i), 32768);
                refused.add(new IH_Transaction__c(Id = rows[i].Id, Business_Status__c = FAILED, Business_Runs__c = rows[i].Business_Runs__c,
                    Business_Error__c = rows[i].Business_Error__c));
            }
        }
        IntegrationHubData.updateEach(refused);
        closeReruns(rows);
    }

    /* A rerun's Integration Attempt says Processing until the job ran; it gets the result here. */
    private static void closeReruns(List<IH_Transaction__c> rows) {
        Map<Id, IH_Transaction__c> byId = new Map<Id, IH_Transaction__c>(rows);
        List<IH_Attempt__c> open = (List<IH_Attempt__c>) IntegrationHubData.query(
            'SELECT Id, Transaction__c FROM IH_Attempt__c WHERE Transaction__c IN :ids AND Kind__c = :k AND Outcome__c = :p',
            new Map<String, Object>{ 'ids' => byId.keySet(), 'k' => KIND_RERUN, 'p' => PROCESSING });
        for (IH_Attempt__c a : open) {
            IH_Transaction__c t = byId.get(a.Transaction__c);
            a.Outcome__c = t.Business_Status__c;
            a.Error_Message__c = t.Business_Error__c;
            a.Error_Summary__c = IntegrationHub.clip(t.Business_Error__c, 255);
        }
        IntegrationHubData.updateEach(open);
    }

    private static void markFailed(List<Id> txnIds, String reason) {
        List<IH_Transaction__c> rows = new List<IH_Transaction__c>();
        for (Id txnId : new Set<Id>(txnIds)) {
            rows.add(new IH_Transaction__c(Id = txnId, Business_Status__c = FAILED, Business_Error__c = reason));
        }
        IntegrationHubData.updateEach(rows);
        closeReruns(rows);
    }

    /**
     * @description Marks the job's transactions still Processing as Failed when the job dies (e.g. a limit in the handler).
     */
    public class Recovery implements Finalizer {
        private final List<Id> txnIds;

        /**
         * @description Recovery for these transactions.
         * @param transactionIds the job's transactions
         */
        public Recovery(List<Id> transactionIds) {
            txnIds = transactionIds;
        }

        /**
         * @description Runs after the job.
         * @param ctx the finalizer context
         */
        public void execute(FinalizerContext ctx) {
            if (ctx.getResult() == ParentJobResult.SUCCESS || txnIds == null || txnIds.isEmpty()) {
                return;
            }
            List<Id> stuck = new List<Id>(new Map<Id, SObject>(IntegrationHubData.query(
                'SELECT Id FROM IH_Transaction__c WHERE Id IN :ids AND Business_Status__c = :p',
                new Map<String, Object>{ 'ids' => txnIds, 'p' => PROCESSING })).keySet());
            String reason = ctx.getException() == null ? 'The background job stopped.'
                : 'The background job stopped: ' + ctx.getException().getMessage();
            markFailed(stuck, reason + ' Use Rerun handler.');
        }
    }
}
